package ca.pkay.rcloneexplorer.util

import ca.pkay.rcloneexplorer.Items.Filter
import ca.pkay.rcloneexplorer.Items.FilterEntry

/**
 * Builds and recognizes the rclone filter rules generated by the task editor's subfolder picker:
 * one "+ /<name>/**" per chosen direct child folder, then a final "- **".
 */
object SubfolderFilterRules {

    const val TITLE_PREFIX = "Subfolders: "
    private const val INCLUDE_SUFFIX = "/**"
    private const val EXCLUDE_ALL = "**"
    private const val GLOB_SPECIALS = "\\*?[]{}"

    fun titleFor(remotePath: String): String = TITLE_PREFIX + remotePath

    fun escapeGlob(name: String): String = buildString {
        for (c in name) {
            if (c in GLOB_SPECIALS) {
                append('\\')
            }
            append(c)
        }
    }

    fun unescapeGlob(pattern: String): String = buildString {
        var i = 0
        while (i < pattern.length) {
            val c = pattern[i]
            if (c == '\\' && i + 1 < pattern.length) {
                append(pattern[i + 1])
                i += 2
            } else {
                append(c)
                i++
            }
        }
    }

    /** Empty input returns an empty list (caller must not persist that). */
    fun buildRules(folderNames: Collection<String>): List<FilterEntry> {
        val names = folderNames
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .distinct()
            .sortedWith(String.CASE_INSENSITIVE_ORDER)
        if (names.isEmpty()) {
            return emptyList()
        }
        val includes = names.map {
            FilterEntry(FilterEntry.FILTER_INCLUDE, "/" + escapeGlob(it) + INCLUDE_SUFFIX)
        }
        return includes + FilterEntry(FilterEntry.FILTER_EXCLUDE, EXCLUDE_ALL)
    }

    /**
     * Returns the folder names when [filter] has exactly the generated shape; null for any
     * hand-made or edited filter so the caller never overwrites user rules.
     */
    fun parseSelectedFolders(filter: Filter?): Set<String>? {
        val entries = filter?.getFilters() ?: return null
        if (entries.size < 2) {
            return null
        }
        val last = entries.last()
        if (last.filterType != FilterEntry.FILTER_EXCLUDE || last.filter != EXCLUDE_ALL) {
            return null
        }
        val names = LinkedHashSet<String>()
        for (entry in entries.dropLast(1)) {
            if (entry.filterType != FilterEntry.FILTER_INCLUDE) {
                return null
            }
            val pattern = entry.filter ?: return null
            if (!pattern.startsWith("/") || !pattern.endsWith(INCLUDE_SUFFIX)) {
                return null
            }
            val middle = pattern.substring(1, pattern.length - INCLUDE_SUFFIX.length)
            if (middle.isEmpty() || middle.contains('/')) {
                return null
            }
            names.add(unescapeGlob(middle))
        }
        return names
    }

    fun isGenerated(filter: Filter?): Boolean = parseSelectedFolders(filter) != null
}
